RG.AIRPORTS = [{"code":"HND","iata":"HND","icao":"RJTT","n":"東京国際空港","nick":"羽田","aka":["東京","羽田空港"],"la":35.55333,"lo":139.78111,"city":"東京","lbl":"東京/羽田","pf":"東京都","mu":"大田区","pax":85900617,"paxy":2024,"rw":3360,"web":"https://tokyo-haneda.com/","img":"Tokyo-International-Airport Satellite.jpg","wp":"東京国際空港","q":"Q204853","kind":"国際","intl":53,"dom":50,"d":"東京国際空港（とうきょうこくさいくうこう、英語: Tokyo International Airport、IATA: HND, ICAO: RJTT）は、東京都大田区羽田空港に所在する日本の国際空港の一つ。通称は羽田空港（はねだくうこう、英: Haneda Airport）。 空港法第4条で法定された首都圏を代表する拠点空港（国管理空港）であり、日本最大のハブ空港として知られている。"},{"code":"NRT","iata":"NRT","icao":"RJAA","n":"成田国際空港","nick":"成田","aka":["東京","成田空港"],"la":35.7649,"lo":140.38845,"city":"東京","lbl":"東京/成田","pf":"千葉県","mu":"成田市","pax":39807651,"paxy":2024,"rw":4000,"web":"https://www.narita-airport.jp/","img":"Narita International Air Port (cropped).jpg","wp":"成田国際空港","q":"Q36454","kind":"国際","intl":93,"dom":20,"d":"成田国際空港（なりたこくさいくうこう、英語: Narita International Airport）は、千葉県成田市にある日本最大の国際空港。略称は成田空港（なりたくうこう、英: Narita Airport）。空港コードはNRT。"},{"code":"KIX","iata":"KIX","icao":"RJBB","n":"関西国際空港","nick":"関西","aka":["関空","大阪"],"la":34.43056,"lo":135.23028,"city":"大阪","lbl":"大阪/関西","pf":"大阪府","mu":"田尻町・泉佐野市","pax":33546700,"paxy":2025,"rw":4000,"web":"https://www.kansai-airport.or.jp/","img":"関西国際空港全体写真20220811.jpg","wp":"関西国際空港","q":"Q193682","kind":"国際","intl":52,"dom":14,"d":"関西国際空港（かんさいこくさいくうこう、英: Kansai International Airport）は、大阪府泉佐野市、泉南郡田尻町、泉南市に所在する、大阪市の南西約40 kmに位置する国際空港。関西圏および西日本の空の玄関口であり、関西三空港の一つとして大阪国際空港（伊丹空港）、神戸空港とともに関西エアポート株式会社によって一体運営が行われている。"},{"code":"FUK","iata":"FUK","icao":"RJFF","n":"福岡空港","nick":"福岡","aka":["板付"],"la":33.58444,"lo":130.45167,"pf":"福岡県","mu":"博多区","pax":26755262,"paxy":2024,"rw":2800,"web":"https://www.fukuoka-airport.jp/","img":"Fukuoka Airport Domestic Terminal.jpg","wp":"福岡空港","q":"Q1137465","kind":"国内","intl":18,"dom":28,"d":"福岡空港（ふくおかくうこう、英: Fukuoka Airport、IATA: FUK, ICAO: RJFF）は、福岡県福岡市博多区にある空港。空港法では第4条第1項第6号に該当する空港として政令で定める空港（国管理空港）に区分されている。2019年4月1日より、福岡国際空港株式会社の運営に移行している。"},{"code":"CTS","iata":"CTS","icao":"RJCC","n":"新千歳空港","nick":"新千歳","aka":["札幌"],"la":42.7752,"lo":141.69228,"city":"札幌","lbl":"札幌/新千歳","pf":"北海道","mu":"千歳市・苫小牧市","pax":23968186,"paxy":2024,"rw":3000,"web":"https://www.hokkaido-airports.com/ja/new-chitose/","img":"Hokkaido New Chitose Airport13n4272.jpg","wp":"新千歳空港","q":"Q908296","kind":"国内","dom":30,"d":"新千歳空港（しんちとせくうこう、英: New Chitose Airport）は、北海道千歳市と苫小牧市にまたがって所在している空港。札幌都市圏の主要空港であり、札幌市内の丘珠空港への路線が存在する場合を除いて航空便の行先として「札幌」の表記が使用される。 なお、本空港（新千歳空港）が1988年（昭和63年）に開港するまで、札幌市の玄関口たる空港、かつ北海道を代表する空港であった千歳空港は、本空港に隣接する千歳飛行場（航空自衛隊 千歳基地）として現在も機能している。"},{"code":"OKA","iata":"OKA","icao":"ROAH","n":"那覇空港","nick":"那覇","aka":["沖縄"],"la":26.19583,"lo":127.64583,"city":"沖縄","lbl":"沖縄/那覇","pf":"沖縄県","mu":"那覇市","pax":21119768,"paxy":2024,"rw":3000,"web":"https://www.naha-airport.co.jp/","img":"Naha Airport12s3s4350.jpg","wp":"那覇空港","q":"Q1197455","kind":"国内","intl":13,"dom":32,"d":"那覇空港（なはくうこう、英: Naha Airport、IATA: OKA, ICAO: ROAH）は、沖縄県那覇市にある空港。国内線の基幹空港で、空港法第4条第1項第6号に該当する空港として政令で定める空港（国管理空港） に区分される。隣接して航空自衛隊那覇基地（英: JASDF Naha Air Base）の施設が併設されている。"},{"code":"ITM","iata":"ITM","icao":"RJOO","n":"大阪国際空港","nick":"伊丹","aka":["大阪","伊丹空港"],"la":34.78553,"lo":135.43822,"city":"大阪","lbl":"大阪/伊丹","pf":"大阪府","mu":"池田市・豊中市","pax":15157501,"paxy":2024,"rw":3000,"web":"https://www.osaka-airport.co.jp","img":"Osaka Airport01.jpg","wp":"大阪国際空港","q":"Q1046748","kind":"国際","dom":37,"d":"大阪国際空港（おおさかこくさいくうこう、英語: Osaka Itami Airport、IATA: ITM, ICAO: RJOO）は、大阪府豊中市、同府池田市、兵庫県伊丹市にまたがる空港。伊丹空港（いたみくうこう、英語: Itami Airport）あるいは大阪空港（おおさかくうこう、英語: Osaka Airport）の通称でも知られる。名前に「国際」と付いており、1994年の関西国際空港開港の前は国際空港であったが、現在は国内線専用の拠点空港（基幹空港）として運用されている。"},{"code":"NGO","iata":"NGO","icao":"RJGG","n":"中部国際空港","nick":"中部","aka":["セントレア","名古屋"],"la":34.85833,"lo":136.80528,"city":"名古屋","lbl":"名古屋/中部","pf":"愛知県","mu":"常滑市","pax":10616189,"paxy":2024,"rw":3500,"web":"https://www.centrair.jp/","img":"Chubu Centrair International Airport - North Wing - 01.JPG","wp":"中部国際空港","q":"Q679345","kind":"国際","intl":22,"dom":24,"d":"中部国際空港（ちゅうぶこくさいくうこう、英: Chubu Centrair International Airport、IATA: NGO, ICAO: RJGG）は、2005年に開港した中部地方（東海地方）の愛知県常滑市にある24時間運用可能な国際空港であり、空港法第4条で法定された拠点空港（会社管理空港）でもある。運営者は中部国際空港株式会社。セントレアの愛称を持つ。"},{"code":"KOJ","iata":"KOJ","icao":"RJFK","n":"鹿児島空港","nick":"鹿児島","la":31.8,"lo":130.72167,"pf":"鹿児島県","mu":"溝辺町麓","pax":5638677,"paxy":2024,"rw":3000,"web":"http://koj-ab.co.jp/en/","img":"Kagoshima Airport01n4592.jpg","wp":"鹿児島空港","q":"Q1156310","kind":"国内","intl":3,"dom":17,"d":"鹿児島空港（かごしまくうこう 英語: Kagoshima Airport、IATA: KOJ, ICAO: RJFK）は、鹿児島県霧島市にある空港。ターミナルビルは霧島市溝辺町麓に位置する。空港法第4条第1項第6号に該当する空港として政令で定める空港（国管理空港）に区分される。"},{"code":"UKB","iata":"UKB","icao":"RJBE","n":"神戸空港","nick":"神戸","aka":["大阪","マリンエア"],"la":34.63278,"lo":135.22389,"city":"大阪","lbl":"大阪/神戸","pf":"兵庫県","mu":"中央区","pax":4172769,"paxy":2025,"rw":2500,"web":"https://www.kairport.co.jp/","img":"Kobe Airport06s5s3200.jpg","wp":"神戸空港","q":"Q741372","kind":"国内","intl":4,"dom":12,"d":"神戸空港（こうべくうこう、英: Kobe Airport）は、兵庫県神戸市中央区の神戸空港島に位置する国際空港。運営は関西エアポート神戸株式会社が行う。愛称はマリンエア。"},{"code":"SDJ","iata":"SDJ","icao":"RJSS","n":"仙台空港","nick":"仙台","la":38.13972,"lo":140.91694,"pf":"宮城県","mu":"名取市・岩沼市","pax":4031331,"paxy":2025,"rw":3000,"web":"https://www.sendai-airport.co.jp/","img":"211028 Sendai Airport Sendai Miyagi prefecture Japan01bs.jpg","wp":"仙台空港","q":"Q1054857","kind":"国内","intl":4,"dom":9,"d":"仙台空港（せんだいくうこう）は、宮城県名取市と岩沼市に跨って位置する東北地方唯一の国管理空港（旧第二種(A)空港）である。2016年7月1日に運営が仙台国際空港株式会社に移管（民営化）された。空港ターミナルビルが名取市にあり、滑走路は岩沼市に跨る。"},{"code":"KMJ","iata":"KMJ","icao":"RJFT","n":"熊本空港","nick":"熊本","aka":["阿蘇くまもと空港"],"la":32.83722,"lo":130.85528,"pf":"熊本県","mu":"益城町・菊陽町","pax":3544043,"paxy":2024,"rw":3000,"web":"https://www.kumamoto-airport.co.jp/","img":"En-Kumamoto Airport 2007.jpg","wp":"熊本空港","q":"Q1199773","kind":"国内","intl":7,"dom":8,"d":"熊本空港（くまもとくうこう、英: Kumamoto Airport、IATA: KMJ, ICAO: RJFT）は、熊本県上益城郡益城町にある空港。2020年4月1日より、熊本国際空港株式会社に運営が移管され、コンセッション方式で民営化された。国際航空輸送網又は国内航空輸送網の拠点となる空港として空港法に基づく区分では第4条第1項第6号に該当する空港として政令で定める空港（国管理空港）に区分されている。"},{"code":"NGS","iata":"NGS","icao":"RJFU","n":"長崎空港","nick":"長崎","la":32.91694,"lo":129.91361,"pf":"長崎県","mu":"比例九州ブロック・大村市","pax":3265501,"paxy":2025,"rw":3000,"web":"https://nagasaki-airport.jp/","img":"Nagasaki Airport Omura Nagasaki pref Japan06n.jpg","wp":"長崎空港","q":"Q133796","kind":"国内","intl":3,"dom":9,"d":"長崎空港（ながさきくうこう、英: Nagasaki Airport、IATA: NGS, ICAO: RJFU）は、長崎県大村市にある空港。空港法では第4条第1項第6号に該当する空港として政令で定める空港（国管理空港）に区分されている。"},{"code":"KMI","iata":"KMI","icao":"RJFM","n":"宮崎空港","nick":"宮崎","aka":["宮崎ブーゲンビリア空港"],"la":31.87722,"lo":131.44861,"pf":"宮崎県","mu":"赤江","pax":3157929,"paxy":2024,"rw":2500,"web":"http://www.miyazaki-airport.co.jp/","img":"Miyazaki Airport Feb 2008.jpg","wp":"宮崎空港","q":"Q1378640","kind":"国内","intl":3,"dom":7,"d":"宮崎空港（みやざきくうこう、英: Miyazaki Airport、IATA: KMI, ICAO: RJFM）は、宮崎県宮崎市大字赤江に所在する空港。愛称は宮崎ブーゲンビリア空港である。"},{"code":"MYJ","iata":"MYJ","icao":"RJOM","n":"松山空港","nick":"松山","la":33.82722,"lo":132.69972,"pf":"愛媛県","mu":"松山市","pax":3000352,"paxy":2024,"rw":2500,"web":"http://www.matsuyama-airport.co.jp/","img":"Matsuyama Airport Terminal Bldg 20090807-001.jpg","wp":"松山空港","q":"Q255345","kind":"国内","intl":3,"dom":7,"d":"松山空港（まつやまくうこう、英: Matsuyama Airport）は、愛媛県松山市にある国管理空港である。"},{"code":"HIJ","iata":"HIJ","icao":"RJOA","n":"広島空港","nick":"広島","la":34.43611,"lo":132.91944,"pf":"広島県","mu":"三原市","pax":2846982,"paxy":2024,"rw":3000,"web":"https://www.hij.airport.jp/","img":"Hiroshima airport japan.jpg","wp":"広島空港","q":"Q82240","kind":"国内","intl":6,"dom":5,"d":"広島空港（ひろしまくうこう、英: Hiroshima Airport）は、広島県三原市本郷町にある空港。空港法では国管理空港に区分されている。運営は2021年4月からコンセッション方式で民間に委託された。"},{"code":"ISG","iata":"ISG","icao":"ROIG","n":"石垣空港","nick":"石垣","aka":["新石垣空港","南ぬ島石垣空港"],"la":24.39639,"lo":124.245,"pf":"沖縄県","mu":"石垣市","pax":2640784,"paxy":2024,"rw":2000,"web":"https://www.ishigaki-airport.co.jp/","img":"Ishigaki new ishigaki airport.jpg","wp":"石垣空港","q":"Q11434817","kind":"国内","intl":4,"dom":10,"d":"石垣空港（いしがきくうこう、英: Ishigaki Airport）は、沖縄県石垣市（石垣島東部）にある地方管理空港である。愛称は「南ぬ島 石垣空港」（ぱいぬしま いしがきくうこう）。2021年現在、定期便が発着する空港としては日本最南端である。"},{"code":"TAK","iata":"TAK","icao":"RJOT","n":"高松空港","nick":"高松","la":34.21417,"lo":134.01556,"pf":"香川県","mu":"高松市","pax":2042634,"paxy":2024,"rw":2500,"web":"https://www.takamatsu-airport.com/","img":"TakamatsuKukou01.jpg","wp":"高松空港","q":"Q1334603","kind":"国内","intl":5,"dom":3,"d":"高松空港（たかまつくうこう、英: Takamatsu Airport）は、香川県高松市にある空港。空港法では第4条第1項第6号に該当する空港として政令で定める空港（国管理空港）に区分されている。滑走路・誘導路の一部は綾歌郡綾川町に属する。"},{"code":"OIT","iata":"OIT","icao":"RJFO","n":"大分空港","nick":"大分","la":33.47944,"lo":131.73722,"pf":"大分県","mu":"国東市","pax":1876979,"paxy":2024,"rw":3000,"web":"https://oita-airport.jp/","img":"Oita Airport Terminal Building.jpg","wp":"大分空港","q":"Q1334587","kind":"国内","intl":2,"dom":4,"d":"大分空港（おおいたくうこう、英: Oita Airport、IATA: OIT, ICAO: RJFO）は、大分県国東市にある空港。空港法では第4条第1項第6号に該当する空港として政令で定める空港（国管理空港）に区分されている。"},{"code":"MMY","iata":"MMY","icao":"ROMY","n":"宮古空港","nick":"宮古","aka":["宮古島"],"la":24.78278,"lo":125.295,"city":"宮古","lbl":"宮古/宮古島","pf":"沖縄県","mu":"宮古島市","pax":1858351,"paxy":2024,"rw":2000,"web":"https://miyakoap.co.jp/","img":"Miyako Airport and its controll tower being repaired just after typhoon.jpg","wp":"宮古空港","q":"Q116725","kind":"国内","dom":7,"d":"宮古空港（みやこくうこう、英: Miyako Airport）は、沖縄県宮古島市（宮古島）にある地方管理空港である。"},{"code":"HKD","iata":"HKD","icao":"RJCH","n":"函館空港","nick":"函館","la":41.77,"lo":140.82194,"pf":"北海道","mu":"函館市","pax":1796905,"paxy":2024,"rw":3000,"web":"https://www.hokkaido-airports.com/ja/hakodate/","img":"Hakodate Airport Hokkaido Japan06s3.jpg","wp":"函館空港","q":"Q1155685","kind":"国内","intl":1,"dom":7,"d":"函館空港（はこだてくうこう、英: Hakodate Airport）は、北海道函館市にある国際空港。IATAはHKD、ICAOはRJCH。北海道南部（道南）における唯一の空港であり、北海道内で新千歳空港に次ぐ旅客数を誇る。"},{"code":"KCZ","iata":"KCZ","icao":"RJOK","n":"高知空港","nick":"高知","aka":["高知龍馬空港"],"la":33.54611,"lo":133.66944,"pf":"高知県","mu":"南国市","pax":1573994,"paxy":2024,"rw":2500,"web":"http://www.kochiap.co.jp/","img":"高知龍馬空港ターミナル - panoramio.jpg","wp":"高知空港","q":"Q1156315","kind":"国内","intl":1,"dom":6,"d":"高知空港（こうちくうこう、英: Kochi Airport）は、高知県南国市にある空港である。空港法第4条第1項第6号に該当する空港として政令で定める空港（国管理空港）に区分されている。愛称は高知龍馬空港（こうちりょうまくうこう、英: Kochi Ryoma Airport）。"},{"code":"KMQ","iata":"KMQ","icao":"RJNK","n":"小松飛行場","nick":"小松","aka":["小松空港","金沢"],"la":36.39389,"lo":136.4075,"pf":"石川県","mu":"小松市","pax":1458720,"paxy":2024,"rw":2700,"web":"https://www.komatsuairport.jp/","img":"Komatsu airport terminal building.jpg","wp":"小松飛行場","q":"Q1141511","kind":"共用","intl":5,"dom":4,"d":"小松飛行場（こまつひこうじょう）は、石川県小松市にある飛行場（空港）である。 防衛省が管理、航空自衛隊小松基地（英: JASDF Komatsu Airbase）と民間航空（民航）が滑走路を共用する飛行場（空港法附則第3条第1項で定める自衛隊共用空港）である。民間の施設は通称として小松空港（こまつくうこう、英: Komatsu Airport）と呼ばれている。"},{"code":"OKJ","iata":"OKJ","icao":"RJOB","n":"岡山空港","nick":"岡山","aka":["岡山桃太郎空港"],"la":34.75694,"lo":133.85528,"pf":"岡山県","mu":"岡山市・中国地方","pax":1337066,"paxy":2024,"rw":3000,"web":"https://www.okayama-airport.org/","img":"Okayama airport terminal.jpg","wp":"岡山空港","q":"Q1322391","kind":"国内","intl":3,"dom":3,"d":"岡山空港（おかやまくうこう、英: Okayama Airport）は、岡山県岡山市北区にある地方管理空港。岡山市中心部の北西15㎞に位置している。愛称は岡山桃太郎空港（おかやまももたろうくうこう）。"},{"code":"AOJ","iata":"AOJ","icao":"RJSA","n":"青森空港","nick":"青森","la":40.73333,"lo":140.68861,"pf":"青森県","mu":"青森市","pax":1327111,"paxy":2025,"rw":3001,"web":"http://www.aomori-airport.jp","img":"Aomori Airport Aerial photograph.2017.jpg","wp":"青森空港","q":"Q628429","kind":"国内","intl":2,"dom":5,"d":"青森空港（あおもりくうこう、英: Aomori Airport）は、青森県青森市にある地方管理空港である。なお、本項では、旧空港開港以前の航空事案についても記述する。"},{"code":"AXT","iata":"AXT","icao":"RJSK","n":"秋田空港","nick":"秋田","la":39.61556,"lo":140.21861,"pf":"秋田県","mu":"秋田市","pax":1244741,"paxy":2024,"rw":2500,"img":"Akita Airport Domestic Terminal 20190602.jpg","wp":"秋田空港","q":"Q1336514","kind":"国内","intl":1,"dom":5,"d":"秋田空港（あきたくうこう、英: Akita Airport）は、秋田県秋田市雄和にある特定地方管理空港。"},{"code":"KKJ","iata":"KKJ","icao":"RJFR","n":"北九州空港","nick":"北九州","la":33.84556,"lo":131.035,"pf":"福岡県","mu":"北九州市門司区","pax":1207098,"paxy":2024,"rw":2500,"web":"https://www.kitakyu-air.jp/","img":"Kitakyushu Airport Access Bridge 1010074.jpg","wp":"北九州空港","q":"Q594223","kind":"国内","intl":3,"dom":2,"d":"北九州空港（きたきゅうしゅうくうこう、英: Kitakyushu Airport、IATA: KKJ, ICAO: RJFR）は、福岡県北九州市小倉南区空港北町と京都郡苅田町空港南町に跨る人工島に位置する空港（海上空港）である。ターミナルビルや空港事務所は北九州市側に所在する。 国際航空輸送網又は国内航空輸送網の拠点となる空港として、空港法の第4条第1項第6号に該当する空港として政令で定める空港（国管理空港）に区分されている。"},{"code":"AKJ","iata":"AKJ","icao":"RJEC","n":"旭川空港","nick":"旭川","la":43.67083,"lo":142.4475,"pf":"北海道","mu":"東神楽町・旭川市","pax":1125378,"paxy":2024,"rw":2500,"web":"https://www.hokkaido-airports.com/ja/asahikawa/","img":"140724 Asahikawa Airport Hokkaido Japan02s3.jpg","wp":"旭川空港","q":"Q387048","kind":"国内","intl":1,"dom":4,"d":"旭川空港（あさひかわくうこう、英: Asahikawa Airport）は、北海道旭川市と上川郡東神楽町にまたがる特定地方管理空港。愛称は北海道のまん中・旭川空港（英: Center of Hokkaido-Asahikawa Airport）。"},{"code":"KIJ","iata":"KIJ","icao":"RJSN","n":"新潟空港","nick":"新潟","la":37.95583,"lo":139.11167,"pf":"新潟県","mu":"新潟市・中部地方","pax":1121775,"paxy":2024,"rw":2500,"img":"Niigata Airport Aerial Photograph.jpg","wp":"新潟空港","q":"Q1197536","kind":"国内","intl":2,"dom":8,"d":"新潟空港（にいがたくうこう、英: Niigata Airport）は、新潟県新潟市東区にある国管理空港。"},{"code":"TKS","iata":"TKS","icao":"RJOS","n":"徳島飛行場","nick":"徳島","aka":["徳島阿波おどり空港","徳島空港"],"la":34.13278,"lo":134.60639,"pf":"徳島県","mu":"松茂町","pax":1044593,"paxy":2024,"rw":2500,"web":"http://www.tokushima-airport.co.jp/english/index.html","img":"Tokushima-Awaodori Airport.jpg","wp":"徳島飛行場","q":"Q1142453","kind":"共用","intl":1,"dom":3,"d":"徳島飛行場（とくしまひこうじょう）は、徳島県板野郡松茂町にある飛行場である。 海上自衛隊徳島航空基地（英: JMSDF Tokushima Airbase）と民間航空機が共用する飛行場で、通称は徳島空港（とくしまくうこう、英: Tokushima Airport）、愛称は徳島阿波おどり空港（とくしまあわおどりくうこう、英: Tokushima Awaodori Airport）。"},{"code":"IZO","iata":"IZO","icao":"RJOC","n":"出雲空港","nick":"出雲","aka":["出雲縁結び空港"],"la":35.41361,"lo":132.89,"pf":"島根県","mu":"出雲市","pax":1035626,"paxy":2024,"rw":2000,"web":"https://www.izumo-airport.co.jp/","img":"150322 Izumo Airport Izumo Shimane pref Japan01s3.jpg","wp":"出雲空港","q":"Q1139412","kind":"国内","intl":1,"dom":9,"d":"出雲空港（いずもくうこう、Izumo Airport）は、島根県出雲市にある地方管理空港。近くにある出雲大社が縁結びの神様であることから「出雲縁結び空港」（いずもえんむすびくうこう、Izumo Enmusubi Airport）の愛称がつけられている。"},{"code":"NKM","iata":"NKM","icao":"RJNA","n":"名古屋飛行場","nick":"小牧","aka":["県営名古屋空港","名古屋"],"la":35.255,"lo":136.92444,"city":"名古屋","lbl":"名古屋/小牧","pf":"愛知県","mu":"小牧市","pax":894954,"paxy":2024,"rw":2740,"web":"http://www.nagoya-airport-bldg.co.jp/","img":"Nagoya airfiled201304.JPG","wp":"名古屋飛行場","q":"Q1322497","kind":"飛行場","dom":9,"d":"名古屋飛行場（なごやひこうじょう、英: Nagoya Airfield）は、愛知県にある飛行場である。名古屋飛行場は航空法上の正式名称であり、空港施設の通称は県営名古屋空港（けんえいなごやくうこう、英: Prefectural Nagoya Airport）。航空自衛隊小牧基地と隣接しているため小牧空港（こまきくうこう）とも呼ばれ、時刻表や発着案内において都市名と併記する際は中部国際空港（セントレア）と明確に区別するため、「名古屋（小牧）」などと記述される。"},{"code":"UBJ","iata":"UBJ","icao":"RJDC","n":"山口宇部空港","nick":"山口宇部","aka":["宇部"],"la":33.93,"lo":131.27861,"pf":"山口県","mu":"宇部市・中国地方","pax":873809,"paxy":2024,"rw":2500,"web":"https://www.yamaguchiube-airport.jp/","img":"Yamaguchi-Ube-Airport.JPG","wp":"山口宇部空港","q":"Q1328906","kind":"国内","dom":1,"d":"山口宇部空港（やまぐちうべくうこう Yamaguchi-Ube Airport）は、山口県宇部市に所在する特定地方管理空港である。本州の空港としては最西端に位置する。"},{"code":"ASJ","iata":"ASJ","icao":"RJKA","n":"奄美空港","nick":"奄美","aka":["奄美大島"],"la":28.43083,"lo":129.7125,"pf":"鹿児島県","mu":"奄美市","pax":861277,"paxy":2024,"rw":2000,"web":"https://amami-airport.co.jp/","img":"Amami.airport.jpg","wp":"奄美空港","q":"Q1430769","kind":"国内","dom":10,"d":"奄美空港（あまみくうこう、英: Amami Airport）は、鹿児島県奄美市（奄美大島）にある地方管理空港。2,000mの滑走路と平行誘導路がある。"},{"code":"MMB","iata":"MMB","icao":"RJCM","n":"女満別空港","nick":"女満別","la":43.88056,"lo":144.16417,"pf":"北海道","mu":"大空町","pax":775634,"paxy":2024,"rw":2500,"web":"https://www.hokkaido-airports.com/ja/memanbetsu/","img":"Memanbetsu Airport02n.jpg","wp":"女満別空港","q":"Q651482","kind":"国内","dom":6,"d":"女満別空港（めまんべつくうこう、英: Memanbetsu Airport）は、北海道網走郡大空町にある地方管理空港である。"},{"code":"IBR","iata":"IBR","icao":"RJAH","n":"百里飛行場","nick":"茨城","aka":["茨城空港","百里"],"la":36.18167,"lo":140.41472,"pf":"茨城県","mu":"小美玉市・関東地方","pax":760423,"paxy":2024,"rw":2700,"web":"http://www.ibaraki-airport.net/","img":"003 Ibaraki Airport, Japan - 百里飛行場-百里基地.JPG","wp":"百里飛行場","q":"Q1156420","kind":"共用","intl":2,"dom":4,"d":"百里飛行場（ひゃくりひこうじょう）は、茨城県小美玉市にある飛行場である。 防衛省・航空自衛隊と民間の共用飛行場であり、民間施設は茨城空港（いばらきくうこう）、自衛隊施設は航空自衛隊百里基地（こうくうじえいたいひゃくりきち）となっている。滑走路と自衛隊施設の大半は百里にあるが、茨城空港の空港ターミナルビルは隣の与沢にある。"},{"code":"KUH","iata":"KUH","icao":"RJCK","n":"釧路空港","nick":"釧路","aka":["たんちょう釧路空港"],"la":43.04083,"lo":144.19306,"pf":"北海道","mu":"釧路市","pax":743506,"paxy":2024,"rw":2500,"web":"https://www.hokkaido-airports.com/ja/kushiro/","img":"Kushiro airport01.JPG","wp":"釧路空港","q":"Q1333925","kind":"国内","dom":6,"d":"釧路空港（くしろくうこう、英: Kushiro Airport）は、北海道釧路市にある空港。空港法では第4条第1項第6号に該当する空港として政令で定める空港（国管理空港）に区分されている。滑走路など施設の一部は白糠郡白糠町に跨る。"},{"code":"YGJ","iata":"YGJ","icao":"RJOH","n":"美保飛行場","nick":"米子","aka":["米子鬼太郎空港","米子空港"],"la":35.49333,"lo":133.23917,"pf":"鳥取県","mu":"境港市","pax":647596,"paxy":2024,"rw":2500,"web":"https://www.yonago-air.com/","img":"YonagoAirport.jpg","wp":"美保飛行場","q":"Q1141913","kind":"共用","intl":2,"dom":1,"d":"美保飛行場（みほひこうじょう）は、鳥取県境港市（敷地の一部は米子市）にある飛行場（空港）である。 防衛省が管理しており、航空自衛隊美保基地（みほきち、JASDF Miho Airbase）の滑走路を民間航空機が利用する共用飛行場である。通称は米子空港（よなごくうこう Yonago Airport）、愛称を米子鬼太郎空港（よなごきたろうくうこう Yonago Kitaro Airport）としている。"},{"code":"OBO","iata":"OBO","icao":"RJCB","n":"帯広空港","nick":"帯広","aka":["とかち帯広空港"],"la":42.73333,"lo":143.21722,"pf":"北海道","mu":"帯広市","pax":647180,"paxy":2024,"rw":2500,"web":"https://www.hokkaido-airports.com/ja/obihiro/","img":"131012 Obihiro Airport Hokkaido Japan01s5.jpg","wp":"帯広空港","q":"Q1332254","kind":"国内","intl":1,"dom":3,"d":"帯広空港（おびひろくうこう、英: Obihiro Airport）は、北海道帯広市の南東部に位置する特定地方管理空港である。国（国土交通省）が設置し、北海道エアポートが管理する。愛称はとかち帯広空港。"},{"code":"HSG","iata":"HSG","icao":"RJFS","n":"佐賀空港","nick":"佐賀","aka":["九州佐賀国際空港"],"la":33.14972,"lo":130.30222,"pf":"佐賀県","mu":"佐賀市","pax":597610,"paxy":2024,"rw":2000,"web":"https://saga-ab.jp","img":"Saga Airport runway, taxiway and tarmac.JPG","wp":"佐賀空港","q":"Q1366663","kind":"国内","intl":2,"dom":1,"d":"佐賀空港（さがくうこう、英: SAGA AIRPORT）は、佐賀県佐賀市川副町大字犬井道にある地方管理空港である。公称は九州佐賀国際空港（きゅうしゅうさがこくさいくうこう、英: KYUSHU-SAGA International AIRPORT）。"},{"code":"FSZ","iata":"FSZ","icao":"RJNS","n":"静岡空港","nick":"静岡","aka":["富士山静岡空港"],"la":34.79611,"lo":138.18944,"pf":"静岡県","mu":"牧之原市・島田市","pax":583372,"paxy":2024,"rw":2500,"web":"https://www.mtfuji-shizuokaairport.jp/","img":"Fujisan-Shizuoka airport,Makinohara-city,Japan.jpg","wp":"静岡空港","q":"Q1209993","kind":"国内","intl":15,"dom":7,"d":"静岡空港（しずおかくうこう、英語: Shizuoka Airport）は、静岡県の牧之原市と島田市に跨る地方管理空港である。 富士山静岡空港（英語: Mt. Fuji Shizuoka Airport）という愛称がつけられている。"},{"code":"OKD","iata":"OKD","icao":"RJCO","n":"札幌飛行場","nick":"丘珠","aka":["札幌","札幌丘珠空港"],"la":43.1175,"lo":141.38139,"city":"札幌","lbl":"札幌/丘珠","pf":"北海道","mu":"札幌市東区","pax":553482,"paxy":2024,"rw":1500,"web":"http://www.okadama-airport.co.jp/eng/index.html","img":"Okadama airport01.JPG","wp":"札幌飛行場","q":"Q2902013","kind":"共用","dom":13,"d":"札幌飛行場（さっぽろひこうじょう、英: Sapporo Airfield）は、北海道札幌市東区丘珠町の陸上自衛隊丘珠駐屯地の飛行場である。共用する民間施設を中心に丘珠空港（おかだまくうこう、英: Okadama Airport）と通称される。"},{"code":"IWK","iata":"IWK","icao":"RJOI","n":"岩国飛行場","nick":"岩国","aka":["岩国錦帯橋空港"],"la":34.145,"lo":132.24417,"pf":"山口県","mu":"岩国市","pax":517562,"paxy":2024,"rw":2440,"web":"http://www.mcasiwakuni.marines.mil/","img":"CVW-5 Aircraft fly in Formation during MCAS Iwakuni Friendship Day (9014066).jpg","wp":"岩国飛行場","q":"Q1030389","kind":"共用","dom":2,"d":"岩国飛行場（いわくにひこうじょう、Marine Corps Air Station(MCAS) IWAKUNI/JMSDF Iwakuni Air Base）は、山口県岩国市に所在し、海上自衛隊とアメリカ海兵隊が共同使用する飛行場・基地。基地名は岩国航空基地（いわくにこうくうきち）で、通称・岩国基地（いわくにきち）。または、その一部を民間航空に用いる空港法上の共用空港。"},{"code":"HNA","iata":"HNA","icao":"RJSI","n":"花巻空港","nick":"花巻","aka":["いわて花巻空港"],"la":39.42861,"lo":141.13528,"pf":"岩手県","mu":"花巻市","pax":487763,"paxy":2024,"rw":2500,"web":"https://www.hna-terminal.co.jp/","img":"Hanamaki airport terminal.jpg","wp":"花巻空港","q":"Q1320088","kind":"国内","intl":1,"dom":5,"d":"花巻空港（はなまきくうこう）は、岩手県花巻市にある地方管理空港である。いわて花巻空港の愛称がある。面積は1,722,278 m2。"},{"code":"SHI","iata":"SHI","icao":"RORS","n":"下地島空港","nick":"下地島","aka":["みやこ下地島空港","宮古"],"la":24.82667,"lo":125.14472,"city":"宮古","lbl":"宮古/下地島","pf":"沖縄県","mu":"宮古島市","pax":470860,"paxy":2024,"rw":3000,"web":"https://shimojishima.jp/","img":"Shimojishima.airport.jpg","wp":"下地島空港","q":"Q654922","kind":"国内","intl":5,"dom":4,"d":"下地島空港（しもじしまくうこう、しもじじまくうこう、英: Shimojishima Airport / Shimojijima Airport）は、沖縄県宮古島市の下地島にある地方管理空港である。旅客ターミナル施設の名称は、みやこ下地島空港ターミナル。"},{"code":"TTJ","iata":"TTJ","icao":"RJOR","n":"鳥取空港","nick":"鳥取","aka":["鳥取砂丘コナン空港"],"la":35.53,"lo":134.1625,"pf":"鳥取県","mu":"鳥取市","pax":399013,"paxy":2024,"rw":2000,"web":"https://www.ttj-ap-bld.co.jp/","img":"Tottori Airport Aerial Photograph.jpg","wp":"鳥取空港","q":"Q1433078","kind":"国内","dom":1,"d":"鳥取空港（とっとりくうこう、英: Tottori Airport）は、鳥取県鳥取市にある空港である。空港法に基づく地方管理空港で、鳥取県が設置・管理する。愛称は鳥取砂丘コナン空港（とっとりさきゅうコナンくうこう、英: Tottori Sand Dunes Conan Airport）。"},{"code":"TOY","iata":"TOY","icao":"RJNT","n":"富山空港","nick":"富山","aka":["富山きときと空港"],"la":36.64833,"lo":137.1875,"pf":"富山県","mu":"富山市","pax":396373,"paxy":2024,"rw":2000,"web":"https://www.toyama-airport.jp/","img":"Toyama Airport.jpg","wp":"富山空港","q":"Q1191625","kind":"国内","intl":3,"dom":2,"d":"富山空港（とやまくうこう、Toyama Airport）は、富山県富山市秋ヶ島にある空港法第5条第1項の規定及び富山県富山空港条例に基づき設置される地方管理空港である。愛称は富山高山すし空港。なお、以前は富山きときと空港（2012年11月9日 - 2026年7月7日）を愛称としていた。"},{"code":"GAJ","iata":"GAJ","icao":"RJSC","n":"山形空港","nick":"山形","aka":["おいしい山形空港"],"la":38.41194,"lo":140.37111,"pf":"山形県","mu":"東根市","pax":361128,"paxy":2024,"rw":2000,"web":"https://www.yamagata-airport.co.jp/","img":"220428 Yamagata Airport Yamagata Yamagata pref Japan01s3.jpg","wp":"山形空港","q":"Q176187","kind":"国内","intl":1,"dom":4,"d":"山形空港（やまがたくうこう、英: Yamagata Airport）は、山形県東根市にある特定地方管理空港である。愛称はおいしい山形空港。"},{"code":"SYO","iata":"SYO","icao":"RJSY","n":"庄内空港","nick":"庄内","aka":["おいしい庄内空港"],"la":38.81222,"lo":139.78722,"pf":"宮城県","mu":"酒田市・東北地方","pax":359396,"paxy":2024,"rw":2000,"web":"http://www.shonai-airport.co.jp/","img":"Shonai Airport Terminal and Tower (cropped).JPG","wp":"庄内空港","q":"Q1927323","kind":"国内","dom":1,"d":"庄内空港（しょうないくうこう、英: Shonai Airport）は、山形県庄内地方の酒田市と鶴岡市にまたがり立地する地方管理空港である。空港ターミナルビルは酒田市浜中に所在している。愛称は「おいしい庄内空港」。"},{"code":"MSJ","iata":"MSJ","icao":"RJSM","n":"三沢飛行場","nick":"三沢","aka":["三沢空港"],"la":40.70528,"lo":141.37194,"pf":"青森県","mu":"三沢市","pax":307812,"paxy":2022,"rw":3050,"web":"https://www.misawa.af.mil/","img":"Misawa Air Base Aerial photograph 1975.jpg","wp":"三沢飛行場","q":"Q1350451","kind":"共用","dom":3,"d":"三沢飛行場（みさわひこうじょう、英: Misawa Air Base）は、青森県三沢市大字三沢字下タ沢にある飛行場。日本で唯一の航空自衛隊、アメリカ空軍、民間航空の三者が使用する飛行場である。管理はアメリカ軍が行っている。"},{"code":"FKS","iata":"FKS","icao":"RJSF","n":"福島空港","nick":"福島","la":37.2275,"lo":140.42806,"pf":"福島県","mu":"須賀川市","pax":261503,"paxy":2024,"rw":2500,"web":"http://www.fks-ab.co.jp/","img":"Fukushima-Airport.jpg","wp":"福島空港","q":"Q177473","kind":"国内","intl":1,"dom":2,"d":"福島空港（ふくしまくうこう、英: Fukushima Airport）は、福島県石川郡玉川村と須賀川市にまたがって位置する地方管理空港である。"},{"code":"TSJ","iata":"TSJ","icao":"RJDT","n":"対馬空港","nick":"対馬","aka":["対馬やまねこ空港"],"la":34.285,"lo":129.33056,"pf":"長崎県","mu":"対馬市","pax":249925,"paxy":2024,"rw":1900,"web":"https://www.tsushima-airport.co.jp/","img":"Tsushimaairport.jpg","wp":"対馬空港","q":"Q1134491","kind":"国内","dom":2,"d":"対馬空港（つしまくうこう、英: Tsushima Airport）は、長崎県対馬市（対馬）にある地方管理空港。愛称は対馬やまねこ空港。"},{"code":"MMJ","iata":"MMJ","icao":"RJAF","n":"松本空港","nick":"松本","aka":["信州まつもと空港"],"la":36.16667,"lo":137.92278,"pf":"長野県","mu":"塩尻市・松本市","pax":249860,"paxy":2024,"rw":2000,"web":"http://www.matsumoto-airport.co.jp/","img":"Matsumoto Airport01s3200.jpg","wp":"松本空港","q":"Q652331","kind":"国内","dom":5,"d":"松本空港（まつもとくうこう、英: Matsumoto Airport）は、長野県松本市と塩尻市にまたがる地方管理空港。日本の空港の中では最も標高が高い場所に位置しており、長野県が設置・管理する。愛称は信州まつもと空港（しんしゅうまつもとくうこう）。"},{"code":"SHM","iata":"SHM","icao":"RJBD","n":"南紀白浜空港","nick":"南紀白浜","aka":["白浜"],"la":33.66222,"lo":135.36444,"pf":"和歌山県","mu":"白浜町","pax":226930,"paxy":2024,"rw":2000,"web":"http://shirahama-airport.jp/","img":"Shirahamaairport.jpg","wp":"南紀白浜空港","q":"Q1064050","kind":"国内","dom":1,"d":"南紀白浜空港（なんきしらはまくうこう、英: Nanki-Shirahama Airport）は、和歌山県西牟婁郡白浜町にある地方管理空港である。観光エリア・南紀に訪れる観光客を中心として利用されている。愛称は「熊野白浜リゾート空港」。"},{"code":"UEO","iata":"UEO","icao":"ROKJ","n":"久米島空港","nick":"久米島","la":26.36361,"lo":126.71389,"pf":"沖縄県","mu":"久米島町","pax":221325,"paxy":2024,"rw":2000,"web":"http://kumejima-airport.co.jp/","img":"JA8936.jpg","wp":"久米島空港","q":"Q3235075","kind":"国内","dom":2,"d":"久米島空港（くめじまくうこう、英: Kumejima Airport）は、沖縄県島尻郡久米島町（久米島）にある地方管理空港である。"},{"code":"SHB","iata":"SHB","icao":"RJCN","n":"中標津空港","nick":"中標津","aka":["根室中標津空港"],"la":43.5775,"lo":144.96,"pf":"北海道","mu":"中標津町","pax":216304,"paxy":2024,"rw":2000,"img":"Nakashibetsu airport01.jpg","wp":"中標津空港","q":"Q1432123","kind":"国内","dom":3,"d":"中標津空港（なかしべつくうこう、英: Nakashibetsu Airport）は、北海道標津郡中標津町にある国管理空港である。設置管理者は北海道。 定期路線を就航している全日空グループでは根室中標津空港（ねむろなかしべつくうこう、英: Nemuro-Nakashibetsu Airport）の名称を使用し、空港ビル運営会社名も根室中標津空港ビル株式会社である。"},{"code":"HAC","iata":"HAC","icao":"RJTH","n":"八丈島空港","nick":"八丈島","la":33.115,"lo":139.78583,"pf":"東京都","mu":"八丈町","pax":211520,"paxy":2024,"rw":2000,"web":"https://hachijoapo.net/","img":"Hachijōjima Airport 01.jpg","wp":"八丈島空港","q":"Q2512004","kind":"国内","dom":1,"d":"八丈島空港（はちじょうじまくうこう、英: Hachijojima Airport）は、東京都八丈町（八丈島）にある地方管理空港である。"},{"code":"KUM","iata":"KUM","icao":"RJFC","n":"屋久島空港","nick":"屋久島","la":30.38556,"lo":130.65917,"pf":"鹿児島県","mu":"屋久島町","pax":206984,"paxy":2024,"rw":1500,"img":"Yakushima airport.JPG","wp":"屋久島空港","q":"Q1433247","kind":"国内","dom":3,"d":"屋久島空港（やくしまくうこう、英: Yakushima Airport）は、鹿児島県熊毛郡屋久島町（屋久島）にある地方管理空港。"},{"code":"TKN","iata":"TKN","icao":"RJKN","n":"徳之島空港","nick":"徳之島","la":27.83639,"lo":128.88139,"pf":"鹿児島県","mu":"天城町","pax":203454,"paxy":2024,"rw":2000,"img":"Tokunoshima Airport (TKN).jpg","wp":"徳之島空港","q":"Q1141847","kind":"国内","dom":4,"d":"徳之島空港（とくのしまくうこう、英: Tokunoshima Airport）は、鹿児島県大島郡天城町（徳之島）にある地方管理空港。愛称は徳之島子宝空港。"},{"code":"ONJ","iata":"ONJ","icao":"RJSR","n":"大館能代空港","nick":"大館能代","aka":["あきた北空港"],"la":40.19194,"lo":140.37167,"pf":"秋田県","mu":"北秋田市","pax":194904,"paxy":2024,"rw":2000,"web":"https://onj-airterminal.com/","img":"Odate-Noshiro Airport 02.jpg","wp":"大館能代空港","q":"Q1016960","kind":"国内","dom":1,"d":"大館能代空港（おおだてのしろくうこう、英: Odate-Noshiro Airport）は、秋田県北秋田市にある地方管理空港である。 愛称はあきた北空港（あきたきたくうこう）であるが、愛称の使用範囲は限定的である。また、ターミナルビルや駐車場などの施設は道の駅大館能代空港と兼用になっている。"},{"code":"WKJ","iata":"WKJ","icao":"RJCW","n":"稚内空港","nick":"稚内","la":45.40444,"lo":141.80222,"pf":"北海道","mu":"稚内市","pax":183403,"paxy":2024,"rw":2200,"web":"https://www.hokkaido-airports.com/ja/wakkanai/","img":"Wakkanai Airport06111.jpg","wp":"稚内空港","q":"Q1368344","kind":"国内","dom":2,"d":"稚内空港（わっかないくうこう、英: Wakkanai Airport）は、北海道稚内市声問村にある国管理空港である。 2023年現在、航空定期便が就航する空港としては、日本の施政権の及ぶ範囲で最北端に位置する。"},{"code":"FUJ","iata":"FUJ","icao":"RJFE","n":"福江空港","nick":"五島福江","aka":["五島つばき空港","福江"],"la":32.66639,"lo":128.83278,"pf":"長崎県","mu":"五島市","pax":179269,"paxy":2024,"rw":2000,"web":"http://www.fuj.ecnet.jp/","img":"Gotoh fukue airport.jpg","wp":"福江空港","q":"Q1431393","kind":"国内","dom":2,"d":"福江空港（ふくえくうこう Fukue Airport）は、長崎県五島市にある地方管理空港である。愛称は特産品にちなんだ「五島つばき空港」。 対外的には「五島福江空港」として案内される。"},{"code":"IWJ","iata":"IWJ","icao":"RJOW","n":"石見空港","nick":"石見","aka":["萩・石見空港"],"la":34.67639,"lo":131.79028,"pf":"島根県","mu":"益田市","pax":137188,"paxy":2024,"rw":2000,"web":"https://hagiiwami.jp/","img":"Hagi-Iwami Airport (IWJ RJOW) 2.jpg","wp":"石見空港","q":"Q1431559","kind":"国内","dom":2,"d":"石見空港（いわみくうこう、英称：Iwami Airport）は、島根県益田市にある地方管理空港である。愛称は萩・石見空港（はぎ・いわみくうこう、英称：Hagi-Iwami Airport）。"},{"code":"OKE","iata":"OKE","icao":"RJKB","n":"沖永良部空港","nick":"沖永良部","aka":["えらぶゆりの島空港"],"la":27.43167,"lo":128.70556,"pf":"鹿児島県","mu":"和泊町","pax":113281,"paxy":2024,"rw":1350,"img":"Oke.JPG","wp":"沖永良部空港","q":"Q2901234","kind":"国内","dom":3,"d":"沖永良部空港（おきのえらぶくうこう、英: Okinoerabu Airport）は、鹿児島県大島郡和泊町（沖永良部島）にある地方管理空港である。愛称はえらぶゆりの島空港。"},{"code":"OGN","iata":"OGN","icao":"ROYN","n":"与那国空港","nick":"与那国","la":24.4675,"lo":122.97972,"pf":"沖縄県","mu":"与那国町","pax":109400,"paxy":2024,"rw":2000,"img":"Terminal building in Yonaguni Airport Ryukyu, JAPAN.jpg","wp":"与那国空港","q":"Q708517","kind":"国内","dom":2,"d":"与那国空港（よなぐにくうこう、英: Yonaguni Airport）は、沖縄県八重山郡与那国町（与那国島）にある地方管理空港である。"},{"code":"TNE","iata":"TNE","icao":"RJFG","n":"種子島空港","nick":"種子島","aka":["コスモポート種子島"],"la":30.605,"lo":130.99167,"pf":"鹿児島県","mu":"中種子町","pax":108313,"paxy":2024,"rw":2000,"img":"Tanenewair.jpg","wp":"種子島空港","q":"Q1432159","kind":"国内","dom":2,"d":"種子島空港（たねがしまくうこう、英: Tanegashima Airport、IATA: TNE, ICAO: RJFG）は、鹿児島県熊毛郡中種子町（種子島）にある地方管理空港である。愛称はコスモポート種子島。"},{"code":"RJTF","icao":"RJTF","n":"調布飛行場","nick":"調布","la":35.67167,"lo":139.52806,"pf":"東京都","mu":"調布市","pax":101458,"paxy":2024,"rw":800,"web":"https://www.kouwan.metro.tokyo.lg.jp/rito/tmg-airport/chofu/","img":"Chofu airport 3.jpg","wp":"調布飛行場","q":"Q970339","kind":"飛行場","dom":4,"d":"調布飛行場（ちょうふひこうじょう、Chofu Airport）は、東京都調布市（一部は三鷹市・府中市にまたがる）に所在する日本の飛行場である。東京都営空港の一つ。正式名称は東京都調布飛行場。"},{"code":"RNJ","iata":"RNJ","icao":"RORY","n":"与論空港","nick":"与論","la":27.04389,"lo":128.40167,"pf":"鹿児島県","mu":"与論町","pax":91610,"paxy":2024,"rw":1200,"img":"Terminal building in Yoron Airport Kagoshima, JAPAN.jpg","wp":"与論空港","q":"Q1927310","kind":"国内","dom":3,"d":"与論空港（よろんくうこう、英: Yoron Airport）は、鹿児島県大島郡与論町（与論島）にある地方管理空港である。"},{"code":"KKX","iata":"KKX","icao":"RJKI","n":"喜界空港","nick":"喜界","la":28.32139,"lo":129.92806,"pf":"鹿児島県","mu":"喜界町","pax":87226,"paxy":2024,"rw":1200,"img":"Kikai.airport2.jpg","wp":"喜界空港","q":"Q1927346","kind":"国内","dom":2,"d":"喜界空港（きかいくうこう、英: Kikai Airport）は、鹿児島県大島郡喜界町（喜界島）にある地方管理空港。"},{"code":"OKI","iata":"OKI","icao":"RJNO","n":"隠岐空港","nick":"隠岐","aka":["隠岐世界ジオパーク空港"],"la":36.17833,"lo":133.32333,"pf":"島根県","mu":"隠岐の島町","pax":74487,"paxy":2024,"rw":2000,"web":"http://www.oki-airport.jp/","img":"Oki airport.JPG","wp":"隠岐空港","q":"Q1148447","kind":"国内","dom":2,"d":"隠岐空港（おきくうこう、Oki Airport）は、島根県隠岐郡隠岐の島町（島後島）にある地方管理空港である。島前地域を含めた隠岐諸島における唯一の空港で、隠岐世界ジオパーク空港（おきせかいジオパークくうこう）の愛称が付けられている。"},{"code":"MBE","iata":"MBE","icao":"RJEB","n":"紋別空港","nick":"紋別","aka":["オホーツク紋別空港"],"la":44.30417,"lo":143.40417,"pf":"北海道","mu":"紋別市","pax":71114,"paxy":2024,"rw":2000,"web":"http://mombetsu.jp/access/plane.html","img":"Monbetsu Airport Aerial photograph.1977.jpg","wp":"紋別空港","q":"Q1432054","kind":"国内","dom":1,"d":"紋別空港（もんべつくうこう、Monbetsu Airport）は、北海道紋別市にある地方管理空港（旧: 第三種空港）である。愛称はオホーツク紋別空港（オホーツクもんべつくうこう Okhotsk-Monbetsu Airport）。また、北海道オホーツク紋別空港という愛称もある。"},{"code":"RIS","iata":"RIS","icao":"RJER","n":"利尻空港","nick":"利尻","la":45.24194,"lo":141.1875,"pf":"北海道","mu":"利尻富士町","pax":60325,"paxy":2024,"rw":1800,"img":"Rishiri-airport.jpg","wp":"利尻空港","q":"Q1049856","kind":"国内","dom":2,"d":"利尻空港（りしりくうこう、英: Rishiri Airport）は、北海道利尻郡利尻富士町（利尻島）にある地方管理空港である。"},{"code":"NTQ","iata":"NTQ","icao":"RJNW","n":"能登空港","nick":"能登","aka":["のと里山空港"],"la":37.29333,"lo":136.96222,"pf":"石川県","mu":"能登町・穴水町","pax":52817,"paxy":2024,"rw":2000,"web":"https://www.noto-airport.jp/","img":"Noto Airport 20160528.jpg","wp":"能登空港","q":"Q1432192","kind":"国内","dom":1,"d":"能登空港（のとくうこう、英: Noto Airport）は、石川県の能登半島北部にある地方管理空港である。通称はのと里山空港（のとさとやまくうこう）。2029年9月30日までの愛称はのと里山ポケモン・ウィズ・ユー空港（のとさとやまポケモン・ウィズ・ユーくうこう）。"},{"code":"MMD","iata":"MMD","icao":"ROMD","n":"南大東空港","nick":"南大東","la":25.84667,"lo":131.26361,"pf":"沖縄県","mu":"南大東村","pax":44548,"paxy":2024,"rw":1500,"img":"Minami Daito ap.jpg","wp":"南大東空港","q":"Q1057877","kind":"国内","dom":1,"d":"南大東空港（みなみだいとうくうこう、英: Minami-Daito Airport）は、沖縄県島尻郡南大東村（南大東島）にある地方管理空港である。 沖縄本島から約360 km東方に位置する南大東島の東側に置かれている。強風時に船が接岸できない自然環境の南大東島において、航空機の就航は重要な役割を担う。"},{"code":"AXJ","iata":"AXJ","icao":"RJDA","n":"天草飛行場","nick":"天草","aka":["天草空港"],"la":32.48222,"lo":130.15889,"pf":"熊本県","mu":"天草市","pax":44125,"paxy":2024,"rw":1000,"web":"http://www.pref.kumamoto.jp/soshiki/137/amakusa120323.html","img":"Amakusa-airport.JPG","wp":"天草飛行場","q":"Q1073798","kind":"飛行場","dom":3,"d":"天草飛行場（あまくさひこうじょう、英: Amakusa Airfield）は、熊本県天草市にある飛行場である。天草空港（あまくさくうこう）とも呼ばれる。"},{"code":"TRA","iata":"TRA","icao":"RORT","n":"多良間空港","nick":"多良間","la":24.65389,"lo":124.67528,"pf":"沖縄県","mu":"多良間村","pax":42757,"paxy":2024,"rw":1500,"img":"Tarama tarama airport 2.jpg","wp":"多良間空港","q":"Q2233042","kind":"国内","dom":2,"d":"多良間空港（たらまくうこう、英: Tarama Airport）は、沖縄県宮古郡多良間村（多良間島）にある地方管理空港である。愛称はかりゆす多良間空港。"},{"code":"TJH","iata":"TJH","icao":"RJBT","n":"但馬飛行場","nick":"但馬","aka":["コウノトリ但馬空港","但馬空港"],"la":35.51278,"lo":134.78694,"pf":"兵庫県","mu":"豊岡市","pax":33958,"paxy":2024,"rw":1200,"web":"https://www.tajima-airport.jp/","img":"TajimaAirport.jpg","wp":"但馬飛行場","q":"Q1931194","kind":"飛行場","dom":1,"d":"但馬飛行場（たじまひこうじょう、英語: Tajima Airport）は、兵庫県豊岡市にある飛行場である。 通称は但馬空港（たじまくうこう）。また、コウノトリ但馬空港（コウノトリたじまくうこう）の愛称がある。"},{"code":"RJAN","icao":"RJAN","n":"新島空港","nick":"新島","la":34.36944,"lo":139.26861,"pf":"東京都","mu":"新島村","pax":33906,"paxy":2024,"rw":800,"img":"Niijima Airport Aerial photograph.1978.jpg","wp":"新島空港","q":"Q2248108","kind":"国内","dom":1,"d":"新島空港（にいじまくうこう、Niijima Airport）は、東京都新島村（新島）にある空港。東京都営空港の一つ。空港法の分類では地方管理空港（旧空港整備法の分類では第三種空港）。"},{"code":"IKI","iata":"IKI","icao":"RJDB","n":"壱岐空港","nick":"壱岐","la":33.74917,"lo":129.78583,"pf":"長崎県","mu":"壱岐島","pax":33809,"paxy":2024,"rw":1200,"img":"Iki Airport.jpg","wp":"壱岐空港","q":"Q1038664","kind":"国内","dom":1,"d":"壱岐空港（いきくうこう、英: Iki Airport）は、長崎県壱岐市にある地方管理空港である。"},{"code":"MYE","iata":"MYE","icao":"RJTQ","n":"三宅島空港","nick":"三宅島","la":34.07361,"lo":139.56028,"pf":"東京都","mu":"三宅村","pax":29213,"paxy":2024,"rw":1200,"img":"Miyakejima Airport Aerial photograph.jpg","wp":"三宅島空港","q":"Q2234528","kind":"国内","dom":1,"d":"三宅島空港（みやけじまくうこう Miyakejima Airport）は、東京都三宅村（三宅島）にあり、東京都が運営する地方管理空港。"},{"code":"KTD","iata":"KTD","icao":"RORK","n":"北大東空港","nick":"北大東","la":25.94472,"lo":131.32694,"pf":"沖縄県","mu":"北大東村","pax":25910,"paxy":2024,"rw":1500,"img":"Ktd.jpg","wp":"北大東空港","q":"Q1930831","kind":"国内","dom":1,"d":"北大東空港（きただいとうくうこう、英: Kitadaito Airport）は、沖縄県島尻郡北大東村（北大東島）に所在する地方管理空港。"},{"code":"RJAZ","icao":"RJAZ","n":"神津島空港","nick":"神津島","la":34.18944,"lo":139.13361,"pf":"東京都","mu":"神津島村","pax":25386,"paxy":2024,"rw":800,"img":"Kozushima airport.JPG","wp":"神津島空港","q":"Q2235009","kind":"国内","dom":1,"d":"神津島空港（こうづしまくうこう、Kozushima Airport）は、東京都神津島村（神津島）に所在する地方管理空港である。"},{"code":"OIM","iata":"OIM","icao":"RJTO","n":"大島空港","nick":"大島","aka":["伊豆大島"],"la":34.78194,"lo":139.36028,"pf":"東京都","mu":"大島町","pax":24459,"paxy":2024,"rw":1800,"img":"Oshima airport aerial-photo.jpg","wp":"大島空港","q":"Q1196909","kind":"国内","dom":1,"d":"大島空港（おおしまくうこう、英: Oshima Airport）は、東京都大島町（伊豆大島）にある、都営の地方管理空港。愛称は東京大島かめりあ空港。"},{"code":"OIR","iata":"OIR","icao":"RJEO","n":"奥尻空港","nick":"奥尻","la":42.07167,"lo":139.43278,"pf":"北海道","mu":"奥尻町","pax":14286,"paxy":2024,"rw":1500,"web":"http://www.town.okushiri.lg.jp/hotnews/hotnews_view.php?id=517","img":"Okushiri airport.jpg","wp":"奥尻空港","q":"Q1432227","kind":"国内","dom":2,"d":"奥尻空港（おくしりくうこう、英: Okushiri Airport）は、北海道奥尻郡奥尻町（奥尻島）にある地方管理空港 である。"},{"code":"AGJ","iata":"AGJ","icao":"RORA","n":"粟国空港","nick":"粟国","la":26.59278,"lo":127.24028,"pf":"沖縄県","mu":"粟国村","pax":1348,"paxy":2024,"rw":800,"img":"Aguni airport Terminal.jpg","wp":"粟国空港","q":"Q252768","kind":"国内","dom":1,"d":"粟国空港（あぐにくうこう、英: Aguni Airport）は、沖縄県島尻郡粟国村（粟国島）に所在する地方管理空港である。"},{"code":"HTR","iata":"HTR","icao":"RORH","n":"波照間空港","nick":"波照間","la":24.05833,"lo":123.80389,"pf":"沖縄県","mu":"竹富町","pax":719,"paxy":2024,"rw":800,"img":"Hateruma-Airport-building-2019.jpg","wp":"波照間空港","q":"Q713881","kind":"国内","dom":0,"d":"波照間空港（はてるまくうこう、英: Hateruma Airport）は、沖縄県八重山郡竹富町の波照間島にある地方管理空港である。島の東端に位置する。"},{"code":"IEJ","iata":"IEJ","icao":"RORE","n":"伊江島空港","nick":"伊江島","la":26.7225,"lo":127.78694,"pf":"沖縄県","mu":"伊江村","pax":460,"paxy":2024,"rw":1500,"img":"Iejima Airport Terminal.JPG","wp":"伊江島空港","q":"Q1368593","kind":"国内","dom":0,"d":"伊江島空港（いえじまくうこう、英: Iejima Airport）は、沖縄県国頭郡伊江村（伊江島）にある地方管理空港である。米軍訓練空域内にあるため運用等の制限や利用客が少なくなったことから、1977年（昭和52年）2月以降、定期便は就航していない。"},{"code":"KJP","iata":"KJP","icao":"ROKR","n":"慶良間空港","nick":"慶良間","la":26.16833,"lo":127.29333,"pf":"沖縄県","mu":"座間味村","pax":109,"paxy":2024,"rw":800,"img":"Kerama airport.JPG","wp":"慶良間空港","q":"Q3273378","kind":"国内","dom":0,"d":"慶良間空港（けらまくうこう、英: Kerama Airport）は、沖縄県島尻郡座間味村の外地島（ふかじしま）にある地方管理空港である。"},{"code":"SDS","iata":"SDS","icao":"RJSD","n":"佐渡空港","nick":"佐渡","la":38.06111,"lo":138.41417,"pf":"新潟県","mu":"佐渡市","rw":890,"img":"Sado Airport.JPG","wp":"佐渡空港","q":"Q1019284","kind":"国内","dom":2,"d":"佐渡空港（さどくうこう、英: Sado Airport）は、新潟県佐渡市（佐渡島）にある地方管理空港である。現在、定期便の就航は無い。"},{"code":"OKS","iata":"OKS","icao":"RJBK","n":"岡南飛行場","nick":"岡南","la":34.59139,"lo":133.93333,"pf":"岡山県","mu":"岡山市","rw":1200,"img":"Kounan airport 1.JPG","wp":"岡南飛行場","q":"Q1019300","kind":"飛行場","dom":0,"d":"岡南飛行場（こうなんひこうじょう、Kohnan Airport）は、岡山県岡山市南区にある、岡山県が設置・管理する飛行場である。旧岡山空港。"},{"code":"RBJ","iata":"RBJ","icao":"RJCR","n":"礼文空港","nick":"礼文","la":45.455,"lo":141.03917,"pf":"北海道","mu":"礼文町","rw":800,"img":"Rebun.airport.jpg","wp":"礼文空港","q":"Q3275961","kind":"国内","dom":0,"d":"礼文空港（れぶんくうこう、英: Rebun Airport）は、北海道礼文郡礼文町（礼文島）船泊村幌泊にある地方管理空港（旧・第三種空港）。日本最北端の空港であり、かつ休港中の空港である（ヘリコプターによる急患搬送などを除く）。 空港の建物は塗装の剥がれなど劣化がみられるものの、礼文町は航空路線の再開を希望しており、北海道庁が年間400万円を支出して維持管理している。"},{"code":"FKJ","iata":"FKJ","icao":"RJNF","n":"福井空港","nick":"福井","la":36.14278,"lo":136.22389,"pf":"福井県","mu":"坂井市","rw":1200,"web":"http://www.fukui-airport.com/","img":"Fukui Airport.jpg","wp":"福井空港","q":"Q3273365","kind":"国内","dom":0,"d":"福井空港（ふくいくうこう、英語:Fukui Airport）は、福井県坂井市春江町江留中にある地方管理空港である。"}];
