RG.AIR_FARE = {"note":"距離(km)から出す概算。公表運賃ではなく比較の目安。full=普通運賃 disc=早割系 low/high=LCC の安い時/高い時","fsc":{"full":{"a":12000,"b":30,"cap":55000},"disc":{"ratio":0.45,"floor":8000}},"mid":{"full":{"ratio":0.8},"disc":{"ratio":0.4}},"lcc":{"low":{"a":3500,"b":6},"high":{"a":9000,"b":14}},"reg":{"full":{"ratio":1.0},"disc":{"ratio":0.5}},"formula":"fsc.full = min(a + b*km, cap); fsc.disc = max(ratio*full, floor); mid/reg = ratio × fsc.full; lcc = a + b*km"};
